 for(const e of all){const name=direct(e,'Name')[0]?.textContent?.trim();if(!name)continue;let crs=[];for(let n=e;n&&n.nodeType===1;n=n.parentElement){crs.push(...direct(n,'CRS').map(a=>a.textContent.trim()),...direct(n,'SRS').flatMap(a=>a.textContent.trim().split(/\s+/)));}result.push({name,title:direct(e,'Title')[0]?.textContent?.trim()||name,crs:[...new Set(crs)],leaf:direct(e,'Layer').length===0});}
