function openPoint(id,c,kind='point'){const f=id?state.features.find(x=>x.id===id):null;const p=f?.properties||{},coords=f?.geometry.coordinates||c||map.center;const suggested=state.settings.compare==='modern'?'manual':state.settings.topoEnabled?state.settings.topo:state.settings.photoEnabled?state.settings.photo:'manual';$('pointId').value=id||'';$('pointTitle').textContent=f?'Editar punto':kind==='camp'?'Marcar puesto':kind==='sounding'?'Registrar profundidad':'Nuevo punto';$('pointName').value=p.name||(kind==='camp'?'Mi puesto':kind==='sounding'?`Sonda ${state.features.filter(x=>x.properties.kind==='sounding').length+1}`:`${kind==='point'?'Punto':KINDS[kind][0]} ${state.features.filter(x=>x.geometry.type==='Point').length+1}`);$('pointKind').value=p.kind||kind;$('pointSource').value=p.source||(kind==='sounding'?'sonar':kind==='camp'?'manual':suggested);$('pointLat').value=coords[1].toFixed(6);$('pointLng').value=coords[0].toFixed(6);$('pointDepth').value=p.depth_m??'';$('pointDate').value=p.observedAt||today();$('pointWater').value=p.waterReference||'';$('pointNotes').value=p.notes||'';$('pointLandmark').value=p.landmark||'';$('pointBottom').value=p.bottom||'';$('useGps').hidden=!gps;updatePointInfo();$('pointVerified').checked=p.verified||false;$('deletePoint').hidden=!f;$('pointDialog').showModal();setTimeout(()=>$('pointName').focus(),50);}
$('pointForm').addEventListener('submit',e=>{e.preventDefault();const coords=[num($('pointLng').value),num($('pointLat').value)];if(!coordOK(coords)){toast('Revisa las coordenadas WGS84: latitud entre −85 y 85, longitud entre −180 y 180.',true);return;}const depth=$('pointDepth').value.trim()===''?null:num($('pointDepth').value);if(depth!==null&&(!Number.isFinite(depth)||depth<0||depth>500)){toast('Introduce una profundidad entre 0 y 500 metros, o deja el campo vacío.',true);return;}if(depth===null&&$('pointKind').value==='sounding'){toast('Una medición de sonda necesita la profundidad.',true);return;}if(depth!==null&&!$('pointDate').value){toast('Añade la fecha de la medición de profundidad.',true);return;}const id=$('pointId').value||uid(),old=state.features.find(f=>f.id===id),now=new Date().toISOString();const f={type:'Feature',id,geometry:{type:'Point',coordinates:coords},properties:{name:$('pointName').value.trim()||'Sin nombre',kind:$('pointKind').value,landmark:$('pointLandmark').value.trim(),bottom:$('pointBottom').value,source:$('pointSource').value,depth_m:depth,observedAt:$('pointDate').value,waterReference:$('pointWater').value.trim(),notes:$('pointNotes').value.trim(),verified:$('pointVerified').checked,createdAt:old?.properties.createdAt||now,updatedAt:now}};if(old)state.features[state.features.indexOf(old)]=f;else state.features.push(f);if(f.properties.kind==='camp'&&!activeCamp())state.activeCampId=id;if(f.properties.kind==='camp'&&!state.activeCampId)state.activeCampId=id;save();renderFeatures();$('pointDialog').close();toast('Punto guardado en este navegador.');});
