async function backup(){const payload={app:'orellana-atlas',schemaVersion:1,exportedAt:new Date().toISOString(),...state};if(!await shareOrDownload(`Orellana_Atlas_${today()}.json`,JSON.stringify(payload,null,2),'application/json','Copia de Orellana Atlas'))return;state.lastBackupAt=new Date().toISOString();save();updateBackupReminder();toast('Copia completa exportada. Guárdala en Archivos o iCloud.');}
// Recordatorio: hay cambios sin copia desde hace más de 3 días (o nunca se hizo una).
function needsBackup(){if(!state.features.length)return false;const last=Date.parse(state.lastBackupAt||0)||0,changed=Math.max(0,...state.features.map(f=>Date.parse(f.properties.updatedAt)||0));return changed>last&&Date.now()-Math.max(last,Math.min(...state.features.map(f=>Date.parse(f.properties.createdAt)||Date.now())))>3*864e5;}
