function exportGPX(){const point=(f)=>{const p=f.properties,c=f.geometry.coordinates;const desc=[p.notes,p.depth_m!==null?`Profundidad registrada: ${p.depth_m} m`:'',p.observedAt?`Fecha: ${p.observedAt}`:'',p.waterReference?`Referencia agua: ${p.waterReference}`:'',`Origen: ${p.source}`].filter(Boolean).join('\n');return `<wpt lat="${c[1]}" lon="${c[0]}"><name>${esc(p.name)}</name><desc>${esc(desc)}</desc><type>${esc(p.kind)}</type><extensions><oa:source>${esc(p.source)}</oa:source>${p.depth_m!==null?`<oa:depth_m>${p.depth_m}</oa:depth_m>`:''}<oa:observedAt>${esc(p.observedAt)}</oa:observedAt><oa:waterReference>${esc(p.waterReference)}</oa:waterReference>${p.landmark?`<oa:landmark>${esc(p.landmark)}</oa:landmark>`:''}${p.bottom?`<oa:bottom>${esc(p.bottom)}</oa:bottom>`:''}</extensions></wpt>`;};const tracks=state.features.filter(f=>f.geometry.type==='LineString').map(f=>`<trk><name>${esc(f.properties.name)}</name><desc>${esc(f.properties.notes)}</desc><trkseg>${f.geometry.coordinates.map(c=>`<trkpt lat="${c[1]}" lon="${c[0]}"/>`).join('')}</trkseg></trk>`);const xml=`<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="Orellana Atlas" xmlns="http://www.topografix.com/GPX/1/1" xmlns:oa="urn:orellana-atlas:1"><metadata><name>Orellana Atlas</name><time>${new Date().toISOString()}</time></metadata>${state.features.filter(f=>f.geometry.type==='Point').map(point).join('')}${tracks.join('')}</gpx>`;download(`Orellana_${today()}.gpx`,xml,'application/gpx+xml');}
function parseGPX(text){const doc=new DOMParser().parseFromString(text,'text/xml');if(doc.querySelector('parsererror'))throw Error('El GPX no es XML válido.');const children=(e,tag)=>Array.from(e.children).find(c=>c.localName===tag)?.textContent||'';const ext=(e,tag)=>Array.from(e.getElementsByTagNameNS('*',tag))[0]?.textContent||'';const f=[];for(const w of Array.from(doc.getElementsByTagNameNS('*','wpt'))){f.push({type:'Feature',geometry:{type:'Point',coordinates:[num(w.getAttribute('lon')),num(w.getAttribute('lat'))]},properties:{name:children(w,'name'),kind:children(w,'type'),notes:children(w,'desc'),source:ext(w,'source')||'import',depth_m:ext(w,'depth_m')||null,observedAt:ext(w,'observedAt'),waterReference:ext(w,'waterReference'),landmark:ext(w,'landmark'),bottom:ext(w,'bottom')}});}for(const tag of ['trkseg','rte'])for(const t of Array.from(doc.getElementsByTagNameNS('*',tag))){const pts=Array.from(t.getElementsByTagNameNS('*',tag==='rte'?'rtept':'trkpt')).map(p=>[num(p.getAttribute('lon')),num(p.getAttribute('lat'))]);f.push({type:'Feature',geometry:{type:'LineString',coordinates:pts},properties:{name:children(tag==='rte'?t:t.parentElement,'name')||'Trazado GPX',notes:children(tag==='rte'?t:t.parentElement,'desc'),source:'import'}});}return f;}
$('fileInput').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('El archivo supera el límite de 5 MB.');const text=await file.text();let data,arr,replace=false;if(file.name.toLowerCase().endsWith('.gpx')||text.trim().startsWith('<'))arr=parseGPX(text);else{data=JSON.parse(text);if(data.app==='orellana-atlas'&&data.schemaVersion===1){if(!confirm('Restaurar esta copia sustituirá los puntos, trazados y ajustes actuales. ¿Continuar?'))return;replace=true;arr=data.features;}else if(data.type==='FeatureCollection')arr=data.features;else if(data.type==='Feature')arr=[data];else throw Error('Formato no reconocido. Usa una copia del atlas, GeoJSON o GPX.');}if(!Array.isArray(arr))throw Error('No se ha encontrado una lista de elementos válida.');if(arr.length>3000)throw Error('Máximo 3.000 elementos por proyecto.');const features=arr.map(normalizedFeature).filter(Boolean),rejected=arr.length-features.length;if(!features.length&&arr.length)throw Error('No hay puntos ni líneas con coordenadas WGS84 válidas.');if(replace){state={settings:normalizeSettings(data.settings),features,activeCampId:typeof data.activeCampId==='string'?data.activeCampId:null,bath:normalizeBath(data.bath),updatedAt:null,lastBackupAt:new Date().toISOString()};map.setView(state.settings.center,state.settings.zoom);applySources();}else{if(state.features.length+features.length>3000)throw Error('El proyecto resultante supera los 3.000 elementos.');let added=0,updated=0,same=0;for(const f of features){const i=state.features.findIndex(x=>x.id===f.id);if(i<0){state.features.push(f);added++;}else if((Date.parse(f.properties.updatedAt)||0)>(Date.parse(state.features[i].properties.updatedAt)||0)){state.features[i]=f;updated++;}else same++;}features.summary=`${added} nuevos · ${updated} actualizados${same?` · ${same} ya estaban`:''}`;if(features.length){const coords=features.flatMap(f=>f.geometry.type==='Point'?[f.geometry.coordinates]:f.geometry.coordinates);map.fit(coords);}}save();renderFeatures();selectTab('points');updateBackupReminder();toast(`${features.summary||`${features.length} elementos importados`}${rejected?` · ${rejected} incompatibles omitidos`:''}.`,rejected>0);}catch(err){toast(err.message||'No se ha podido importar el archivo.',true);}});
